    dp = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        dp[x][y] = val
    for i in range(N - 1, -1, -1):
        for j in range(i + 1, N + 1):
            dp[i][j] = max(dp[i][j], dp[i][j - 1], dp[i + 1][j], dp[i][j] + dp[i + 1][j - 1])
