def max_happiness(n, m, items):
    # Initialize a 2D array to store the results of subproblems
    dp = [[0] * (m+1) for _ in range(n+1)]

    # Fill the first row of the 2D array with the importance values of the items
    for i in range(m+1):
        if i == 0:
            continue
        dp[0][i] = items[i-1][1]

    # Fill the first column of the 2D array with the prices of the items
    for j in range(n+1):
        if j == 0:
            continue
        dp[j][0] = items[j-1][0]

    # Fill the rest of the 2D array with the max of the two choices
    for i in range(1, n+1):
        for j in range(1, m+1):
            dp[i][j] = max(dp[i-1][j], dp[i][j-1] + items[j-1][1])

    # Return the maximum importance value that can be achieved without exceeding the budget
    return dp[n][m]

def max_energy(beads):
    # Initialize the maximum energy as 0
    max_energy = 0

    # Initialize the number of beads as the length of the list
    n = len(beads)

    # Initialize a 2D array to store the dynamic programming results
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Fill in the top row of the 2D array with the head values of the beads
    for i in range(n):
        dp[i][n] = beads[i]

    # Fill in the leftmost column of the 2D array with the tail values of the beads
    for j in range(n):
        dp[n][j] = beads[j]

    # Loop through the 2D array and calculate the maximum energy for each subset of beads
    for i in range(n - 1, -1, -1):
        for j in range(n, 0, -1):
            if i == j:
                dp[i][j] = dp[i + 1][j]
            elif i == n and j == 0:
                dp[i][j] = dp[i][j + 1]
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j + 1], dp[i + 1][j + 1] * beads[i])

    # Return the maximum energy obtained by merging all beads
    return dp[0][0]

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i in range(len(coeffs)):
        if coeffs[i] == 0:
            continue
        term = ''
        if i == 0:
            term += str(abs(coeffs[i]))
        else:
            term += ('-' if coeffs[i] < 0 else '+') + str(abs(coeffs[i]))
        if i > 0:
            term += 'x'
        if i > 1:
            term += '^' + str(i)
        terms.append(term)
    return ' '.join(terms)

