def largest_prime_factor(n: int) -> int:
    smallest_prime = 2
    while smallest_prime ** 2 <= n:
        if n % smallest_prime == 0:
            return n // smallest_prime
        smallest_prime += 1
    return n

def count_partitions(n, k, x):
    # Base case: if n is less than x, return 0
    if n < x:
        return 0

    # Base case: if k is 1, return 1
    if k == 1:
        return 1

    # Recursive case: count the number of ways to partition n - x into k - 1 parts
    return count_partitions(n - x, k - 1, x) + count_partitions(n, k - 1, x)

def count_sequences(n, last, memo):
    if n == 0:
        return 1
    if n not in memo:
        memo[n] = 0
        for i in range(1, last//2+1):
            memo[n] += count_sequences(n-1, i, memo)
    return memo[n]

