def is_prime(num: int) -> bool:
    # Edge case for numbers less than or equal to 1
    if num <= 1:
        return False
    # Case for small numbers (2 and 3) which are prime
    if num == 2 or num == 3:
        return True
    # Check for divisibility by 2 and 3
    if num % 2 == 0 or num % 3 == 0:
        return False
    # Use a 6k +/- 1 optimization to test for factors up to the square root of the number
    for i in range(5, int(num ** 0.5) + 1, 6):
        if num % i == 0 or num % (i + 2) == 0:
            return False
    return True

