def minimum_students_to_leave(heights):
    if len(heights) <= 1:
        return 0
    heights.sort(reverse=True)
    left = 0
    right = len(heights) - 1
    choir_formation = [heights[left]]
    while left < right:
        if heights[right] < choir_formation[left]:
            choir_formation.append(heights[right])
            right -= 1
        else:
            choir_formation.insert(left + 1, heights[right])
            left += 1
            right -= 1
    return len(heights) - len(choir_formation)

